alter table public.api_keys add column if not exists scope_type text not null default 'schools' check (scope_type in ('schools','central','mixed'));
alter table public.api_keys add column if not exists all_schools boolean not null default false;
update public.api_keys set all_schools = (school_ids is null),
  scope_type = case when scopes ? 'notices' and coalesce((scopes->'notices'->>'read')::boolean, false) then 'mixed' else 'schools' end;

alter table public.api_inbox drop constraint if exists api_inbox_status_check;
alter table public.api_inbox add constraint api_inbox_status_check check (status in ('pending','approved','rejected','failed','cancelled'));

create table public.api_resource_settings (
  org_id uuid not null references public.organizations(id) on delete cascade,
  resource text not null,
  enabled boolean not null default true,
  reason text,
  updated_by uuid,
  updated_at timestamptz not null default now(),
  primary key (org_id, resource)
);
create table public.api_resource_events (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  resource text not null,
  enabled boolean not null,
  reason text,
  actor uuid,
  at timestamptz not null default now()
);
create index api_resource_events_org on public.api_resource_events(org_id, at desc);
grant all on public.api_resource_settings, public.api_resource_events to service_role;
alter table public.api_resource_settings enable row level security;
alter table public.api_resource_events enable row level security;
create policy "no direct access" on public.api_resource_settings as restrictive for all to authenticated, anon using (false) with check (false);
create policy "no direct access" on public.api_resource_events as restrictive for all to authenticated, anon using (false) with check (false);

